<!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="csrf-token" content="{{ csrf_token() }}"><title>دخول إدارة المخزون — Doctor Bike</title><link rel="stylesheet" href="{{ asset('inventory-web/portal.css') }}"></head>
<body class="login-body"><main class="login-card"><div class="brand">Doctor Bike</div><h1>إدارة المخزون والجرد</h1><p class="muted">المعرض والمستودع في مكان واحد</p><form id="login-form" class="stack"><label>البريد الإلكتروني<input name="email" type="email" dir="ltr" autocomplete="username" required></label><label>كلمة المرور<input name="password" type="password" dir="ltr" autocomplete="current-password" required></label><button class="primary" type="submit">تسجيل الدخول</button><p id="login-error" role="alert" class="error"></p></form></main>
<script>document.getElementById('login-form').addEventListener('submit',async e=>{e.preventDefault();const form=e.currentTarget,button=form.querySelector('button'),error=document.getElementById('login-error');button.disabled=true;error.textContent='';try{const response=await fetch(@json(url('/inventory/login')),{method:'POST',credentials:'same-origin',headers:{'Accept':'application/json','X-CSRF-TOKEN':document.querySelector('meta[name="csrf-token"]').content,'X-Requested-With':'XMLHttpRequest'},body:new FormData(form)});const data=await response.json();if(!response.ok)throw Error(data.message||'تعذر تسجيل الدخول.');location.href=data.redirect;}catch(e){error.textContent=e.message;}finally{button.disabled=false;}});</script></body></html>
